230		content = clean(content)
231		constraints = clean(constraints)
232		followOwner = clean(followOwner)
233		if err := requireNonEmpty("事项内容", content); err != nil {
234			return Item{}, err
235		}
236		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
237			return Item{}, err
238		}
239		if !severity.valid() {
240			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
241		}
242	
243		var created Item
244		err := svc.store.mutate(func(d *Data) error {
245			sh, _ := findShift(d, shiftID)
246			if sh == nil {
247				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
248			}
249			if sh.Closed {
250				return fmt.Errorf("%w：班次 %s 已结束，不能新增事项", ErrShiftClosed, sh.ID)
251			}
252			d.ItemSeq++
253			now := svc.now()
254			created = Item{
255				ID:             fmt.Sprintf("I%03d", d.ItemSeq),
256				OriginShiftID:  sh.ID,
257				ShiftIDs:       []string{sh.ID},
258				CurrentShiftID: sh.ID,
259				Content:        content,
260				Severity:       severity,
261				Constraints:    constraints,
262				FollowOwner:    followOwner,
263				CreatedAt:      now,
264				Events: []ItemEvent{
265					{At: now, Kind: "created", Detail: "事项建立"},
266				},
267			}
268			d.Items = append(d.Items, created)
269			return nil
270		})
271		if err != nil {
272			return Item{}, err
273		}
274		// 返回独立副本：调用方保留的新增结果与系统保存的事项脱离，
275		// 改动结果不影响存储，也不会在后续正常保存时被带进存储。
276		return cloneItem(created), nil
277	}
