1	package handover
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9	)
10	
11	// Data 是落盘的完整数据。
12	type Data struct {
13		ShiftSeq    int           `json:"shift_seq"`
14		ItemSeq     int           `json:"item_seq"`
15		HandoverSeq int           `json:"handover_seq"`
16		NoteSeq     int           `json:"note_seq"`
17		Shifts      []Shift       `json:"shifts"`
18		Items       []Item        `json:"items"`
19		Handovers   []Handover    `json:"handovers"`
20		Notes       []OverlapNote `json:"notes"`
21	}
22	
23	// Store 是本地 JSON 文件存储。所有业务操作先改内存再原子写盘，
24	// 写盘失败时内存变更一并回滚，保证“失败前已保存的数据保持不变”。
25	type Store struct {
26		path string
27		data Data
28	}
29	
30	// Open 打开数据文件；文件不存在时创建空数据。
31	func Open(path string) (*Store, error) {
32		s := &Store{path: path}
33		b, err := os.ReadFile(path)
34		if err != nil {
35			if errors.Is(err, os.ErrNotExist) {
36				return s, nil
37			}
38			return nil, fmt.Errorf("读取数据文件失败: %w", err)
39		}
40		if len(b) == 0 {
41			return s, nil
42		}
43		if err := json.Unmarshal(b, &s.data); err != nil {
44			return nil, fmt.Errorf("数据文件已损坏: %w", err)
45		}
46		return s, nil
47	}
48	
49	// Path 返回数据文件路径。
50	func (s *Store) Path() string { return s.path }
51	
52	// commit 先把当前数据写进临时文件再改名落盘，失败返回错误且不影响既有文件。
53	func (s *Store) commit() (err error) {
54		if dir := filepath.Dir(s.path); dir != "" && dir != "." {
55			if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
56				return fmt.Errorf("创建数据目录失败: %w", mkErr)
57			}
58		}
59		b, err := json.MarshalIndent(s.data, "", "  ")
60		if err != nil {
61			return err
62		}
63		tmp := s.path + ".tmp"
64		if err = os.WriteFile(tmp, b, 0o644); err != nil {
65			return fmt.Errorf("写入数据文件失败: %w", err)
66		}
67		if err = os.Rename(tmp, s.path); err != nil {
68			_ = os.Remove(tmp)
69			return fmt.Errorf("保存数据文件失败: %w", err)
70		}
71		return nil
72	}
73	
74	// mutate 在数据快照上执行业务变更；业务失败或写盘失败都回滚到快照。
75	// 快照采用深拷贝：写盘失败时内存中的数据也必须恢复到变更前，
76	// 避免出现“文件未写成、内存已改半套”的情况。
77	func (s *Store) mutate(fn func(*Data) error) error {
78		raw, err := json.Marshal(s.data)
79		if err != nil {
80			return err
81		}
82		var snapshot Data
83		if err := json.Unmarshal(raw, &snapshot); err != nil {
84			return err
85		}
86		if err := fn(&s.data); err != nil {
87			s.data = snapshot
88			return err
89		}
90		if err := s.commit(); err != nil {
91			s.data = snapshot
92			return err
93		}
94		return nil
95	}
96

